def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    strong_pressure = 0.0
    weak_count = 0
    urgent_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                urgent_opp_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                if bid > strong_pressure:
                    strong_pressure = bid
                if bid <= DAILY_SALARY * 0.45:
                    weak_count += 1

    if not alive_opponents:
        return float(min(budget, max(1.0, DAILY_SALARY * 0.2)))

    contested = len(alive_opponents) >= 2
    scarce = supply < WATER_REQ * 1.4
    very_urgent = hp <= 2 or no_water_days >= 2
    urgent = hp <= 3 or no_water_days >= 1

    if prev_bids:
        top_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        top_prev = DAILY_SALARY * 0.6
        avg_prev = DAILY_SALARY * 0.5

    if very_urgent:
        target = max(DAILY_SALARY * 0.95, top_prev + 2.0)
    elif urgent:
        target = max(DAILY_SALARY * 0.78, top_prev + 1.0 if top_prev < DAILY_SALARY * 1.15 else DAILY_SALARY * 0.9)
    else:
        if scarce and contested:
            target = max(DAILY_SALARY * 0.52, avg_prev * 0.72)
        else:
            target = DAILY_SALARY * 0.38

    if supply >= 24:
        target *= 0.72
    elif supply >= 21:
        target *= 0.84
    elif supply <= 16:
        target *= 1.08

    if urgent_opp_count >= 2 and not urgent:
        target *= 0.9
    if weak_count == len(prev_bids) and len(prev_bids) > 0 and urgent:
        target = max(target, top_prev + 0.5)

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 1.2
    elif day <= 9:
        reserve = DAILY_SALARY * 0.5

    spend_cap = budget - reserve
    if very_urgent:
        spend_cap = budget
    elif spend_cap < DAILY_SALARY * 0.25:
        spend_cap = min(budget, DAILY_SALARY * 0.5)

    bid = min(budget, max(0.0, min(target, spend_cap)))

    if urgent and bid < DAILY_SALARY * 0.55:
        bid = min(budget, DAILY_SALARY * 0.55)
    if very_urgent and bid < DAILY_SALARY * 0.9:
        bid = min(budget, DAILY_SALARY * 0.9)

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', None)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are effectively contested.
    # Use explicit int() to avoid float index issues.
    # If supply is low, being too conservative risks losing water.
    supply_units = int(supply // float(WATER_REQ)) if WATER_REQ > 0 else 0
    if supply_units < 1:
        supply_units = 1

    # Base aggressiveness: conservative unless pressure is high or my HP is low.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        pressure = 1.0
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        pressure = 0.6
    else:
        pressure = 0.3

    # If I'm in danger, bid more.
    danger = 0.0
    if hp <= 2:
        danger = 1.0
    elif hp <= 4:
        danger = 0.7
    elif no_water_days >= 2:
        danger = 0.5
    else:
        danger = 0.2

    # Combine: target bid around a fraction of salary plus a small bump under pressure.
    # Keep under budget.
    target = DAILY_SALARY * (0.35 + 0.25 * pressure + 0.35 * danger)

    # If supply is relatively abundant, we can underbid more.
    if supply >= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        target *= 0.9

    # If supply is tight, bid closer to salary.
    if supply <= MIN_SUPPLY + 1.0:
        target *= 1.1

    # If yesterday max bid was extremely high, slightly increase to avoid losing the water war.
    if highest_prev_bid >= DAILY_SALARY * 0.95:
        target = max(target, highest_prev_bid * 0.7)

    # Final cap by budget.
    bid = max(0.0, min(budget, target))

    # Ensure we don't bid trivially low when HP is critical.
    if hp <= 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.85))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
